DROP POLICY IF EXISTS "aether project files upload own" ON storage.objects;
CREATE POLICY "aether project files upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'aether-project-files' AND split_part(name, '/', 1) = (select auth.uid())::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.owner_id = (select auth.uid()) AND p.id::text = split_part(name, '/', 2)));
DROP POLICY IF EXISTS "aether project files read own" ON storage.objects;
CREATE POLICY "aether project files read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'aether-project-files' AND split_part(name, '/', 1) = (select auth.uid())::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.owner_id = (select auth.uid()) AND p.id::text = split_part(name, '/', 2)));
DROP POLICY IF EXISTS "aether project files update own" ON storage.objects;
CREATE POLICY "aether project files update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'aether-project-files' AND split_part(name, '/', 1) = (select auth.uid())::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.owner_id = (select auth.uid()) AND p.id::text = split_part(name, '/', 2))) WITH CHECK (bucket_id = 'aether-project-files' AND split_part(name, '/', 1) = (select auth.uid())::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.owner_id = (select auth.uid()) AND p.id::text = split_part(name, '/', 2)));
DROP POLICY IF EXISTS "aether project files delete own" ON storage.objects;
CREATE POLICY "aether project files delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'aether-project-files' AND split_part(name, '/', 1) = (select auth.uid())::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.owner_id = (select auth.uid()) AND p.id::text = split_part(name, '/', 2)));
